begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table cd_fx(k text primary key,id uuid,v jsonb);
grant all on cd_fx to authenticated;
insert into cd_fx(k,id)select k,gen_random_uuid()from unnest(array['actor','other','session','other_session','proposal','review','rejected','reject_action','stale','signed'])k;
create function pg_temp.cd_id(key text)returns uuid language sql as $$select id from cd_fx where k=$1$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'dictation-'||id||'@example.test','{}'from cd_fx where k in('actor','other');
update profiles set is_active=true,full_name='Synthetic dictation staff'where id in(pg_temp.cd_id('actor'),pg_temp.cd_id('other'));
insert into user_roles(user_id,role)values(pg_temp.cd_id('actor'),'STAFF'),(pg_temp.cd_id('other'),'STAFF')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.cd_id('session'),pg_temp.cd_id('actor'),now(),now()),(pg_temp.cd_id('other_session'),pg_temp.cd_id('other'),now(),now());
select ok(relrowsecurity and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('authenticated',oid,'INSERT')and not has_table_privilege('service_role',oid,'SELECT'),relname||' is private')from pg_class where relnamespace='public'::regnamespace and relname in('clinical_dictation_proposals','clinical_dictation_reviews','clinical_dictation_actions');
select ok(has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' exposes only its guarded staff RPC')from pg_proc where pronamespace='public'::regnamespace and proname in('read_clinical_dictation','save_clinical_dictation_action','recover_clinical_dictation_action');
select ok(not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' is owner-only')from pg_proc where pronamespace='public'::regnamespace and proname in('clinical_dictation_actor','clinical_dictation_validate_sections');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.cd_id('actor'),'session_id',pg_temp.cd_id('session'))::text,true);
set local role authenticated;
insert into cd_fx(k,id)select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Dictation','+13035555351','dictation-sql@example.test','EMAIL',null,null);
insert into cd_fx(k,id)select 'pet',id from save_patient(null,pg_temp.cd_id('client'),null,'Synthetic Dictation','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cd_fx(k,id)select 'other_pet',id from save_patient(null,pg_temp.cd_id('client'),null,'Other Dictation','Cat','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cd_fx(k,id)select 'encounter',id from save_clinical_encounter(null,pg_temp.cd_id('pet'),null,now(),'clinic','Synthetic clinic','Original history','Original exam','Original assessment','Original plan');
insert into cd_fx(k,v)values('sections','{"subjective":{"text":"Cough for two days.","quote":"cough for two days"},"objective":{"text":"","quote":""},"assessment":{"text":"","quote":""},"plan":{"text":"","quote":""}}');
insert into cd_fx(k,v)select 'request',jsonb_build_object('pet_id',pg_temp.cd_id('pet'),'encounter_id',pg_temp.cd_id('encounter'),'expected_version',1,'transcript','Owner reports cough for two days. No exam was dictated.','source_note','Synthetic authorized staff transcript','attest_authorized',true,'sections',(select v from cd_fx where k='sections'));
select is(read_clinical_dictation(auth.uid(),pg_temp.cd_id('pet'),pg_temp.cd_id('encounter'))->'items','[]'::jsonb,'Initially no imported drafts');
select throws_ok($$select read_clinical_dictation(pg_temp.cd_id('other'),pg_temp.cd_id('pet'),pg_temp.cd_id('encounter'))$$,'42501',null,'Actor spoof rejected');
select throws_ok($$select read_clinical_dictation(auth.uid(),pg_temp.cd_id('other_pet'),pg_temp.cd_id('encounter'))$$,'23514',null,'Wrong patient rejected');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'submit',(select v||'{"attest_authorized":false}'from cd_fx where k='request'))$$,'23514',null,'Authorization must be explicit');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'submit',(select v||'{"unexpected":true}'from cd_fx where k='request'))$$,'23514',null,'Unknown request keys rejected');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'submit',(select jsonb_set(v,'{sections,subjective,quote}','"not spoken"')from cd_fx where k='request'))$$,'23514',null,'Excerpt must resolve to transcript');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'submit',(select jsonb_set(v,'{sections,objective}','{"text":"Normal exam","quote":""}')from cd_fx where k='request'))$$,'23514',null,'Unspoken normals cannot be imported without a source excerpt');
insert into cd_fx(k,v)select 'submitted',save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('proposal'),'submit',(select v from cd_fx where k='request'));
select is((select subjective from clinical_encounters where id=pg_temp.cd_id('encounter')),'Original history','Import does not alter chart');
select is((select version from clinical_encounters where id=pg_temp.cd_id('encounter')),1,'Import does not advance encounter version');
select is(save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('proposal'),'submit',(select v from cd_fx where k='request')),(select v from cd_fx where k='submitted'),'Exact import retry recovers original receipt');
select is(recover_clinical_dictation_action(auth.uid(),pg_temp.cd_id('proposal'),'submit',(select v from cd_fx where k='request')),(select v from cd_fx where k='submitted'),'Read-only recovery returns original receipt');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('proposal'),'submit',(select v||'{"source_note":"Changed"}'from cd_fx where k='request'))$$,'23505',null,'Changed UUID request rejected');
insert into cd_fx(k,v)select 'review_request',jsonb_build_object('pet_id',pg_temp.cd_id('pet'),'encounter_id',pg_temp.cd_id('encounter'),'expected_version',1,'proposal_id',pg_temp.cd_id('proposal'),'decision','accepted','accepted_sections',jsonb_build_object('subjective','Reviewed cough history.'),'review_note','Reviewed synthetic source.','attest_reviewed',true);
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',(select v||'{"accepted_sections":{}}'from cd_fx where k='review_request'))$$,'23514',null,'No empty acceptance');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',(select v||'{"accepted_sections":{"objective":"Invented normal"}}'from cd_fx where k='review_request'))$$,'23514',null,'Cannot accept a section with no proposed source');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',(select v||'{"attest_reviewed":false}'from cd_fx where k='review_request'))$$,'23514',null,'Review attestation required');
insert into cd_fx(k,v)select 'accepted',save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('review'),'review',(select v from cd_fx where k='review_request'));
select is((select subjective from clinical_encounters where id=pg_temp.cd_id('encounter')),'Reviewed cough history.','Accepted reviewer wording saved');
select is((select jsonb_build_array(objective,assessment,plan)from clinical_encounters where id=pg_temp.cd_id('encounter')),'["Original exam","Original assessment","Original plan"]'::jsonb,'Unselected sections remain identical');
select is((select status from clinical_encounters where id=pg_temp.cd_id('encounter')),'draft','Acceptance does not sign');
select is((select version from clinical_encounters where id=pg_temp.cd_id('encounter')),2,'Acceptance advances encounter exactly once');
select is(save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('review'),'review',(select v from cd_fx where k='review_request')),(select v from cd_fx where k='accepted'),'Acceptance retry returns original receipt');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',(select v from cd_fx where k='review_request'))$$,'PT409',null,'A different UUID cannot review twice');
select is(read_clinical_dictation(auth.uid(),pg_temp.cd_id('pet'),pg_temp.cd_id('encounter'))#>>'{items,0,review,decision}','accepted','History exposes reviewed decision');
update cd_fx set v=v||'{"expected_version":2}'where k='request';
select save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('rejected'),'submit',(select v from cd_fx where k='request'));
select save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('stale'),'submit',(select v from cd_fx where k='request'));
select save_clinical_encounter(pg_temp.cd_id('encounter'),pg_temp.cd_id('pet'),2,now(),'clinic','Synthetic clinic','Other clinician changed this','Original exam','Original assessment','Original plan');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',(select v||jsonb_build_object('expected_version',2,'proposal_id',pg_temp.cd_id('stale'))from cd_fx where k='review_request'))$$,'PT409',null,'Competing saved edit blocks stale proposal');
select save_clinical_dictation_action(auth.uid(),pg_temp.cd_id('reject_action'),'review',(select v||jsonb_build_object('expected_version',2,'proposal_id',pg_temp.cd_id('rejected'),'decision','rejected','accepted_sections','{}'::jsonb,'review_note','Wrong attribution; retained for review')from cd_fx where k='review_request'));
select is((select version from clinical_encounters where id=pg_temp.cd_id('encounter')),3,'Rejecting stale proposal does not edit encounter');
select sign_clinical_encounter(pg_temp.cd_id('encounter'),3);
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'submit',(select v||'{"expected_version":4}'from cd_fx where k='request'))$$,'PT409',null,'Signed encounter rejects new import');
select throws_ok($$select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',(select v||jsonb_build_object('expected_version',2,'proposal_id',pg_temp.cd_id('stale'))from cd_fx where k='review_request'))$$,'PT409',null,'Signed encounter rejects acceptance');
select throws_ok($$select * from clinical_dictation_proposals$$,'42501',null,'Raw transcript SELECT denied');
reset role;
select is((select source_hash from clinical_dictation_proposals where id=pg_temp.cd_id('proposal')),encode(extensions.digest('Owner reports cough for two days. No exam was dictated.','sha256'),'hex'),'Retained source hash matches exact transcript');
select is((select sections from clinical_dictation_proposals where id=pg_temp.cd_id('proposal')),(select v from cd_fx where k='sections'),'Original proposed text retained after reviewer edits');
select is((select actor_id from clinical_dictation_reviews where id=pg_temp.cd_id('review')),pg_temp.cd_id('actor'),'Review attributed to current actor');
select throws_ok($$update clinical_dictation_proposals set transcript='rewrite'$$,'23514',null,'Source history immutable');
select throws_ok($$delete from clinical_dictation_reviews$$,'23514',null,'Review history cannot be deleted');
select throws_ok($$update clinical_dictation_actions set request='{}'$$,'23514',null,'Action identity immutable');
delete from auth.sessions where id=pg_temp.cd_id('session');
set local role authenticated;
select throws_ok($$select read_clinical_dictation(auth.uid(),pg_temp.cd_id('pet'),pg_temp.cd_id('encounter'))$$,'42501',null,'Retired session cannot read source history');
reset role;
select * from finish();
rollback;
